sp_widget.client_script:
api.controller = function($window) {

    var c = this;


    /* =====================================================
       STATE
       ===================================================== */

    c.loading = true;

    c.searchText = '';

    c.statusFilter = '';

    c.selectedApplication = null;


    /* =====================================================
       SIDEBAR
       ===================================================== */

    /*
     * Desktop:
     * Sidebar starts OPEN.
     *
     * Mobile:
     * Sidebar starts CLOSED.
     */

    c.sidebarOpen =
        $window.innerWidth > 900;


    /*
     * SAME 3-LINE BUTTON BEHAVIOR
     *
     * The button is located in the TOP BAR,
     * outside the sidebar.
     *
     * Therefore it always remains visible.
     */

    c.toggleSidebar = function() {

        c.sidebarOpen =
            !c.sidebarOpen;

    };


    c.closeSidebar = function() {

        c.sidebarOpen = false;

    };


    /* =====================================================
       NAVIGATION
       ===================================================== */

    c.navigate = function(pageId) {

        if (!pageId) {
            return;
        }


        c.closeSidebar();


        var studentId =
            'STU_TEST_001';


        if (
            c.data &&
            c.data.student &&
            c.data.student.student_id
        ) {

            studentId =
                c.data.student.student_id;

        }


        window.location.href =
            '?id=' +
            encodeURIComponent(pageId) +
            '&student=' +
            encodeURIComponent(studentId);

    };


    /* =====================================================
       LOAD APPLICATIONS
       ===================================================== */

    c.loadApplications = function() {

        c.loading = true;


        c.server.get({

            action:
                'load_applications'

        }).then(

            function(response) {


                if (
                    response &&
                    response.data
                ) {

                    c.data =
                        response.data;

                }


                c.loading = false;

            },


            function() {

                c.loading = false;

            }

        );

    };


    /* =====================================================
       REFRESH
       ===================================================== */

    c.refresh = function() {

        if (c.loading) {
            return;
        }


        c.loadApplications();

    };


    /* =====================================================
       FILTER
       ===================================================== */

    c.filteredApplications =
        function() {


        if (
            !c.data ||
            !c.data.applications
        ) {

            return [];

        }


        var search =
            (c.searchText || '')
            .toLowerCase()
            .trim();


        var status =
            (c.statusFilter || '')
            .toLowerCase()
            .trim();


        return c.data.applications.filter(

            function(application) {


                var searchable = [

                    application.application_id,

                    application.opportunity_title,

                    application.company,

                    application.location,

                    application.opportunity_type

                ]
                .join(' ')
                .toLowerCase();


                var searchMatch =
                    !search ||
                    searchable.indexOf(search) !== -1;


                var applicationStatus =
                    (
                        application.application_status ||
                        ''
                    )
                    .toLowerCase();


                var statusMatch =
                    !status ||
                    applicationStatus.indexOf(status) !== -1;


                return (
                    searchMatch &&
                    statusMatch
                );

            }

        );

    };


    /* =====================================================
       CLEAR FILTERS
       ===================================================== */

    c.clearFilters = function() {

        c.searchText = '';

        c.statusFilter = '';

    };


    /* =====================================================
       VIEW APPLICATION
       ===================================================== */

    c.viewApplication =
        function(application) {

            c.selectedApplication =
                application;

        };


    /* =====================================================
       CLOSE APPLICATION
       ===================================================== */

    c.closeApplication =
        function(event) {


            if (
                event &&
                event.target !==
                event.currentTarget
            ) {

                return;

            }


            c.selectedApplication =
                null;

        };


    /* =====================================================
       STATUS COLOR
       ===================================================== */

    c.getStatusClass =
        function(status) {


        var value =
            (status || '')
            .toLowerCase();


        if (
            value.indexOf('selected') !== -1 ||
            value.indexOf('accepted') !== -1 ||
            value.indexOf('offer') !== -1
        ) {

            return 'status-green';

        }


        if (
            value.indexOf('shortlist') !== -1 ||
            value.indexOf('interview') !== -1
        ) {

            return 'status-blue';

        }


        if (
            value.indexOf('submitted') !== -1 ||
            value.indexOf('pending') !== -1 ||
            value.indexOf('review') !== -1
        ) {

            return 'status-purple';

        }


        if (
            value.indexOf('reject') !== -1 ||
            value.indexOf('withdraw') !== -1
        ) {

            return 'status-red';

        }


        return 'status-orange';

    };


    /* =====================================================
       INITIALS
       ===================================================== */

    c.getInitials =
        function(name) {


        if (!name) {
            return 'C';
        }


        var parts =
            name
            .trim()
            .split(/\s+/);


        if (parts.length === 1) {

            return parts[0]
                .substring(0, 2)
                .toUpperCase();

        }


        return (

            parts[0].charAt(0) +

            parts[
                parts.length - 1
            ].charAt(0)

        ).toUpperCase();

    };


    /* =====================================================
       INITIAL LOAD
       ===================================================== */

    c.loadApplications();

};

sp_widget.css:
/* ========================================================= 
   CAMPUS360 APPLICATIONS 
   FULL VIEWPORT 
   DARK PURPLE SIDEBAR 
   WHITE TOP NAVBAR 
   DARK PURPLE APPLICATIONS HERO 
   ========================================================= */ 
 
 
/* ========================================================= 
   GLOBAL 
   ========================================================= */ 
 
html, 
body { 
 
  width: 100% !important; 
  height: 100% !important; 
 
  margin: 0 !important; 
  padding: 0 !important; 
 
  overflow: hidden !important; 
 
} 
 
 
/* ========================================================= 
   REMOVE SERVICENOW SYSTEM ADMINISTRATOR NAVBAR 
   ========================================================= */ 
 
body:has(.campus360-applications) #sp-header, 
body:has(.campus360-applications) header#sp-header, 
body:has(.campus360-applications) .sp-header, 
body:has(.campus360-applications) .sp-header-bar, 
body:has(.campus360-applications) .sp-navbar, 
body:has(.campus360-applications) #sp-nav, 
body:has(.campus360-applications) #sp-nav-bar, 
body:has(.campus360-applications) .sp-nav, 
body:has(.campus360-applications) .sp-nav-bar, 
body:has(.campus360-applications) .portal-header, 
body:has(.campus360-applications) .portal-header-wrapper, 
body:has(.campus360-applications) .service-portal-header, 
body:has(.campus360-applications) .sp-page-header, 
body:has(.campus360-applications) .sp-page-header-wrapper, 
body:has(.campus360-applications) .header-wrapper, 
body:has(.campus360-applications) .navbar-header, 
body:has(.campus360-applications) .navbar, 
body:has(.campus360-applications) .navbar-default, 
body:has(.campus360-applications) .navbar-inverse, 
body:has(.campus360-applications) nav.navbar, 
body:has(.campus360-applications) header[role="banner"], 
body:has(.campus360-applications) nav[role="navigation"] { 
 
  display: none !important; 
 
  visibility: hidden !important; 
  opacity: 0 !important; 
 
  width: 0 !important; 
  height: 0 !important; 
 
  min-width: 0 !important; 
  min-height: 0 !important; 
 
  max-width: 0 !important; 
  max-height: 0 !important; 
 
  margin: 0 !important; 
  padding: 0 !important; 
 
  border: 0 !important; 
 
  overflow: hidden !important; 
 
} 
 
 
/* EXTRA SERVICE NOW HEADER SAFETY */ 
 
body:has(.campus360-applications) > header, 
body:has(.campus360-applications) > nav { 
 
  display: none !important; 
 
} 
 
 
/* ========================================================= 
   REMOVE SERVICENOW HEADER SPACE 
   ========================================================= */ 
 
body:has(.campus360-applications) #sp-container, 
body:has(.campus360-applications) #sp-page, 
body:has(.campus360-applications) .sp-page, 
body:has(.campus360-applications) .sp-container, 
body:has(.campus360-applications) .page { 
 
  margin-top: 0 !important; 
  padding-top: 0 !important; 
 
} 
 
 
/* ========================================================= 
   SERVICENOW WRAPPERS 
   ========================================================= */ 
 
body:has(.campus360-applications) .container, 
body:has(.campus360-applications) .container-fluid, 
body:has(.campus360-applications) .row, 
body:has(.campus360-applications) [class*="col-"], 
body:has(.campus360-applications) .well, 
body:has(.campus360-applications) .panel { 
 
  width: 100% !important; 
 
  max-width: none !important; 
 
  min-width: 0 !important; 
 
  margin: 0 !important; 
 
  padding-left: 0 !important; 
  padding-right: 0 !important; 
 
} 
 
 
body:has(.campus360-applications) .panel-body { 
 
  width: 100% !important; 
 
  max-width: none !important; 
 
  margin: 0 !important; 
 
  padding: 0 !important; 
 
} 
 
 
/* ========================================================= 
   CAMPUS360 ROOT 
   ========================================================= */ 
 
.campus360-applications { 
 
  position: fixed !important; 
 
  inset: 0 !important; 
 
  width: 100vw !important; 
  height: 100vh !important; 
 
  min-width: 100vw !important; 
  min-height: 100vh !important; 
 
  max-width: 100vw !important; 
  max-height: 100vh !important; 
 
  margin: 0 !important; 
  padding: 0 !important; 
 
  display: block !important; 
 
  overflow: hidden !important; 
 
  background: #f3f6fb !important; 
 
  color: #101828 !important; 
 
  font-family: 
    Inter, 
    -apple-system, 
    BlinkMacSystemFont, 
    "Segoe UI", 
    Arial, 
    sans-serif !important; 
 
  -webkit-font-smoothing: antialiased !important; 
 
  z-index: 999999 !important; 
 
} 
 
 
/* GLOBAL BOX SIZING */ 
 
.campus360-applications *, 
.campus360-applications *::before, 
.campus360-applications *::after { 
 
  box-sizing: border-box !important; 
 
} 
 
 
/* ========================================================= 
   SIDEBAR 
   DARK PURPLE 
   ========================================================= */ 
 
.c360-left-sidebar { 
 
  position: absolute !important; 
 
  top: 0 !important; 
  left: 0 !important; 
  bottom: 0 !important; 
 
  width: 285px !important; 
 
  min-width: 285px !important; 
  max-width: 285px !important; 
 
  height: 100vh !important; 
 
  z-index: 100 !important; 
 
  display: flex !important; 
 
  flex-direction: column !important; 
 
  overflow: hidden !important; 
 
  background: 
    linear-gradient( 
      180deg, 
      #130d2f 0%, 
      #160d38 48%, 
      #100a29 100% 
    ) !important; 
 
  border-right: 
    1px solid #2d2157 !important; 
 
  color: #ffffff !important; 
 
  box-shadow: 
    4px 0 20px rgba(15,10,40,.18) !important; 
 
  transition: 
    transform .25s ease !important; 
 
} 
 
 
/* CLOSED */ 
 
.campus360-applications.sidebar-closed 
.c360-left-sidebar { 
 
  transform: 
    translateX(-105%) !important; 
 
} 
 
 
/* ========================================================= 
   SIDEBAR BRAND 
   ========================================================= */ 
 
.c360-sidebar-brand { 
 
  height: 
    88px !important; 
 
  min-height: 
    88px !important; 
 
  flex: 
    0 0 88px !important; 
 
  padding: 
    0 20px !important; 
 
  display: 
    flex !important; 
 
  align-items: 
    center !important; 
 
  gap: 
    12px !important; 
 
  border-bottom: 
    1px solid rgba(255,255,255,.08) !important; 
 
  background: 
    transparent !important; 
 
} 
 
 
.c360-brand-logo { 
 
  width: 
    48px !important; 
 
  height: 
    48px !important; 
 
  min-width: 
    48px !important; 
 
  display: 
    flex !important; 
 
  align-items: 
    center !important; 
 
  justify-content: 
    center !important; 
 
  border-radius: 
    14px !important; 
 
  background: 
    linear-gradient( 
      135deg, 
      #7c3aed, 
      #9333ea 
    ) !important; 
 
  color: 
    #ffffff !important; 
 
  font-size: 
    23px !important; 
 
  font-weight: 
    900 !important; 
 
  box-shadow: 
    0 7px 18px rgba(124,58,237,.34) !important; 
 
} 
 
 
.c360-brand-name { 
 
  min-width: 
    0 !important; 
 
} 
 
 
.c360-brand-name strong { 
 
  display: 
    block !important; 
 
  color: 
    #ffffff !important; 
 
  font-size: 
    20px !important; 
 
  line-height: 
    1.05 !important; 
 
  font-weight: 
    900 !important; 
 
} 
 
 
.c360-brand-name span { 
 
  display: 
    block !important; 
 
  margin-top: 
    4px !important; 
 
  color: 
    #c4b5fd !important; 
 
  font-size: 
    11px !important; 
 
  font-weight: 
    800 !important; 
 
} 
 
 
/* ========================================================= 
   STUDENT PROFILE 
   ========================================================= */ 
 
.c360-sidebar-student { 
 
  margin: 
    18px 13px 10px !important; 
 
  min-height: 
    67px !important; 
 
  padding: 
    12px !important; 
 
  flex: 
    0 0 auto !important; 
 
  display: 
    flex !important; 
 
  align-items: 
    center !important; 
 
  gap: 
    10px !important; 
 
  border: 
    1px solid #3c2b69 !important; 
 
  border-radius: 
    14px !important; 
 
  background: 
    linear-gradient( 
      145deg, 
      #1f1448, 
      #21154d 
    ) !important; 
 
  color: 
    #ffffff !important; 
 
  text-decoration: 
    none !important; 
 
  box-shadow: 
    0 6px 18px rgba(0,0,0,.16) !important; 
 
  transition: 
    .2s ease !important; 
 
} 
 
 
.c360-sidebar-student:hover { 
 
  border-color: 
    #5b3ea2 !important; 
 
  background: 
    linear-gradient( 
      145deg, 
      #271957, 
      #2b1c61 
    ) !important; 
 
  box-shadow: 
    0 8px 20px rgba(124,58,237,.18) !important; 
 
} 
 
 
.c360-sidebar-avatar { 
 
  width: 
    43px !important; 
 
  height: 
    43px !important; 
 
  min-width: 
    43px !important; 
 
  display: 
    flex !important; 
 
  align-items: 
    center !important; 
 
  justify-content: 
    center !important; 
 
  border-radius: 
    50% !important; 
 
  background: 
    linear-gradient( 
      135deg, 
      #8b5cf6, 
      #7c3aed 
    ) !important; 
 
  color: 
    #ffffff !important; 
 
  font-size: 
    11px !important; 
 
  font-weight: 
    900 !important; 
 
  box-shadow: 
    0 6px 16px rgba(124,58,237,.28) !important; 
 
} 
 
 
.c360-sidebar-student-info { 
 
  min-width: 
    0 !important; 
 
  flex: 
    1 !important; 
 
} 
 
 
.c360-sidebar-student-info strong { 
 
  display: 
    block !important; 
 
  max-width: 
    185px !important; 
 
  overflow: 
    hidden !important; 
 
  white-space: 
    nowrap !important; 
 
  text-overflow: 
    ellipsis !important; 
 
  color: 
    #ffffff !important; 
 
  font-size: 
    13px !important; 
 
  font-weight: 
    900 !important; 
 
} 
 
 
.c360-sidebar-student-info span { 
 
  display: 
    block !important; 
 
  margin-top: 
    3px !important; 
 
  color: 
    #b9add7 !important; 
 
  font-size: 
    10px !important; 
 
  font-weight: 
    600 !important; 
 
} 
 
 
.c360-student-arrow { 
 
  color: 
    #aaa0c2 !important; 
 
  font-size: 
    21px !important; 
 
} 
 
 
/* ========================================================= 
   SIDEBAR NAVIGATION 
   SCROLLABLE / NO VISIBLE SCROLLBAR 
   ========================================================= */ 
 
.c360-sidebar-nav { 
 
  flex: 
    1 1 auto !important; 
 
  min-height: 
    0 !important; 
 
  padding: 
    2px 8px 12px !important; 
 
  overflow-y: 
    auto !important; 
 
  overflow-x: 
    hidden !important; 
 
  scrollbar-width: 
    none !important; 
 
  -ms-overflow-style: 
    none !important; 
 
} 
 
 
.c360-sidebar-nav::-webkit-scrollbar { 
 
  width: 
    0 !important; 
 
  height: 
    0 !important; 
 
  display: 
    none !important; 
 
} 
 
 
.c360-sidebar-nav::-webkit-scrollbar-track { 
 
  background: 
    transparent !important; 
 
} 
 
 
.c360-sidebar-nav::-webkit-scrollbar-thumb { 
 
  background: 
    transparent !important; 
 
} 
 
 
/* ========================================================= 
   NAV HEADINGS 
   ========================================================= */ 
 
.c360-nav-group { 
 
  margin-bottom: 
    4px !important; 
 
} 
 
 
.c360-nav-heading { 
 
  padding: 
    17px 9px 8px !important; 
 
  color: 
    #9f94bd !important; 
 
  font-size: 
    10px !important; 
 
  font-weight: 
    900 !important; 
 
  line-height: 
    1 !important; 
 
  letter-spacing: 
    .11em !important; 
 
} 
 
 
/* ========================================================= 
   NAV LINK 
   ========================================================= */ 
 
.c360-nav-link { 
 
  position: 
    relative !important; 
 
  width: 
    100% !important; 
 
  min-height: 
    46px !important; 
 
  margin: 
    3px 0 !important; 
 
  padding: 
    9px 12px !important; 
 
  display: 
    flex !important; 
 
  align-items: 
    center !important; 
 
  gap: 
    12px !important; 
 
  border: 
    0 !important; 
 
  border-radius: 
    11px !important; 
 
  background: 
    transparent !important; 
 
  color: 
    #ddd8e8 !important; 
 
  font-size: 
    14px !important; 
 
  font-weight: 
    750 !important; 
 
  text-decoration: 
    none !important; 
 
  transition: 
    background .2s ease, 
    color .2s ease, 
    transform .2s ease !important; 
 
} 
 
 
.c360-nav-link:hover { 
 
  color: 
    #ffffff !important; 
 
  background: 
    rgba(124,58,237,.16) !important; 
 
  transform: 
    translateX(2px) !important; 
 
} 
 
 
.c360-nav-link.active { 
 
  color: 
    #ffffff !important; 
 
  background: 
    linear-gradient( 
      90deg, 
      #7c3aed 0%, 
      #8b3ff2 100% 
    ) !important; 
 
  font-weight: 
    900 !important; 
 
  box-shadow: 
    0 7px 18px rgba(124,58,237,.28) !important; 
 
} 
 
 
.c360-nav-link.active::before { 
 
  content: 
    "" !important; 
 
  position: 
    absolute !important; 
 
  left: 
    0 !important; 
 
  top: 
    8px !important; 
 
  bottom: 
    8px !important; 
 
  width: 
    4px !important; 
 
  border-radius: 
    0 4px 4px 0 !important; 
 
  background: 
    #c4b5fd !important; 
 
} 
 
 
/* ========================================================= 
   NAV ICON 
   ========================================================= */ 
 
.c360-nav-icon { 
 
  width: 
    24px !important; 
 
  height: 
    24px !important; 
 
  min-width: 
    24px !important; 
 
  display: 
    flex !important; 
 
  align-items: 
    center !important; 
 
  justify-content: 
    center !important; 
 
  color: 
    #b8aecb !important; 
 
} 
 
 
.c360-nav-link:hover 
.c360-nav-icon { 
 
  color: 
    #ffffff !important; 
 
} 
 
 
.c360-nav-link.active 
.c360-nav-icon { 
 
  color: 
    #ffffff !important; 
 
} 
 
 
.c360-nav-icon svg { 
 
  width: 
    21px !important; 
 
  height: 
    21px !important; 
 
  fill: 
    none !important; 
 
  stroke: 
    currentColor !important; 
 
  stroke-width: 
    1.8 !important; 
 
  stroke-linecap: 
    round !important; 
 
  stroke-linejoin: 
    round !important; 
 
} 
 
 
.c360-nav-text { 
 
  min-width: 
    0 !important; 
 
  flex: 
    1 !important; 
 
  white-space: 
    nowrap !important; 
 
} 
 
 
.c360-nav-count { 
 
  min-width: 
    23px !important; 
 
  height: 
    23px !important; 
 
  margin-left: 
    auto !important; 
 
  padding: 
    0 6px !important; 
 
  display: 
    flex !important; 
 
  align-items: 
    center !important; 
 
  justify-content: 
    center !important; 
 
  border-radius: 
    50% !important; 
 
  background: 
    rgba(139,92,246,.30) !important; 
 
  color: 
    #ddd6fe !important; 
 
  border: 
    1px solid rgba(196,181,253,.08) !important; 
 
  font-size: 
    11px !important; 
 
  font-weight: 
    900 !important; 
 
} 
 
 
/* ========================================================= 
   SIDEBAR FOOTER 
   ========================================================= */ 
 
.c360-sidebar-footer { 
 
  flex: 
    0 0 auto !important; 
 
  padding: 
    10px 12px 13px !important; 
 
  border-top: 
    1px solid rgba(255,255,255,.08) !important; 
 
  background: 
    #120c2d !important; 
 
} 
 
 
.c360-journey-mini { 
 
  padding: 
    12px !important; 
 
  border-radius: 
    12px !important; 
 
  background: 
    linear-gradient( 
      145deg, 
      #1e143f, 
      #21164a 
    ) !important; 
 
  border: 
    1px solid #382963 !important; 
 
} 
 
 
.c360-journey-label { 
 
  color: 
    #a69abd !important; 
 
  font-size: 
    9px !important; 
 
  font-weight: 
    900 !important; 
 
  letter-spacing: 
    .08em !important; 
 
} 
 
 
.c360-journey-progress { 
 
  height: 
    7px !important; 
 
  margin-top: 
    9px !important; 
 
  border-radius: 
    8px !important; 
 
  overflow: 
    hidden !important; 
 
  background: 
    #30234f !important; 
 
} 
 
 
.c360-journey-fill { 
 
  height: 
    100% !important; 
 
  border-radius: 
    8px !important; 
 
  background: 
    linear-gradient( 
      90deg, 
      #7c3aed, 
      #a855f7 
    ) !important; 
 
} 
 
 
.c360-journey-score { 
 
  margin-top: 
    6px !important; 
 
  color: 
    #c1b7d3 !important; 
 
