/* ========================================================= 
   BRIEF 
   ========================================================= */ 
 
.brief-grid { 
 
  display: 
    grid !important; 
 
  grid-template-columns: 
    1fr 1fr !important; 
 
  gap: 
    8px !important; 
 
  margin-top: 
    17px !important; 
 
} 
 
 
.brief-item { 
 
  min-height: 
    61px !important; 
 
  padding: 
    10px 11px !important; 
 
  border-radius: 
    9px !important; 
 
  border: 
    1px solid #dce6f1 !important; 
 
  background: 
    #f7f9fc !important; 
 
} 
 
 
.brief-item:nth-child(1) { 
 
  background: 
    #f0f7ff !important; 
 
  border-color: 
    #bad8ff !important; 
 
} 
 
 
.brief-item:nth-child(2) { 
 
  background: 
    #f5f0ff !important; 
 
  border-color: 
    #d2c0ff !important; 
 
} 
 
 
.brief-item:nth-child(3) { 
 
  background: 
    #fff7e9 !important; 
 
  border-color: 
    #ffd69a !important; 
 
} 
 
 
.brief-item:nth-child(4) { 
 
  background: 
    #effaf5 !important; 
 
  border-color: 
    #b3e7cb !important; 
 
} 
 
 
.brief-item span, 
.response-row span { 
 
  display: 
    block !important; 
 
  color: 
    #667d99 !important; 
 
  font-size: 
    8px !important; 
 
  font-weight: 
    900 !important; 
 
  letter-spacing: 
    1px !important; 
 
} 
 
 
.brief-item strong { 
 
  display: 
    block !important; 
 
  margin-top: 
    5px !important; 
 
  color: 
    #172d49 !important; 
 
  font-size: 
    11px !important; 
 
  line-height: 
    1.3 !important; 
 
} 
 
 
/* ========================================================= 
   RESPONSE 
   ========================================================= */ 
 
.response-row { 
 
  margin-top: 
    12px !important; 
 
  padding: 
    11px 12px !important; 
 
  border-radius: 
    9px !important; 
 
  border: 
    1px solid #e0e7ef !important; 
 
  background: 
    #f8fafc !important; 
 
} 
 
 
.response-row strong { 
 
  display: 
    block !important; 
 
  margin-top: 
    4px !important; 
 
  color: 
    #6336d0 !important; 
 
  font-size: 
    12px !important; 
 
} 
 
 
/* ========================================================= 
   CARD FOOTER 
   ========================================================= */ 
 
.card-footer { 
 
  margin-top: 
    13px !important; 
 
  padding-top: 
    13px !important; 
 
  display: 
    flex !important; 
 
  justify-content: 
    flex-end !important; 
 
  border-top: 
    1px solid #e0e7ef !important; 
 
} 
 
 
.view-btn { 
 
  min-height: 
    39px !important; 
 
  padding: 
    0 15px !important; 
 
  border: 
    1px solid #bba2ff !important; 
 
  border-radius: 
    9px !important; 
 
  background: 
    #f2ecff !important; 
 
  color: 
    #6031cc !important; 
 
  font-size: 
    11px !important; 
 
  font-weight: 
    850 !important; 
 
