} 
 
 
/* ========================================================= 
   EMPTY STATE 
   ========================================================= */ 
 
.empty-state { 
 
  padding: 
    55px 20px !important; 
 
  text-align: 
    center !important; 
 
  background: 
    #ffffff !important; 
 
  border: 
    1px dashed #cbd8e7 !important; 
 
  border-radius: 
    16px !important; 
 
} 
 
 
.empty-icon { 
 
  width: 
    55px !important; 
 
  height: 
    55px !important; 
 
  margin: 
    auto !important; 
 
  display: 
    flex !important; 
 
  align-items: 
    center !important; 
 
  justify-content: 
    center !important; 
 
  border-radius: 
    14px !important; 
 
  background: 
    #eee8ff !important; 
 
  color: 
    #6b3cda !important; 
 
  font-size: 
    25px !important; 
 
} 
 
 
.empty-state h3 { 
 
  margin: 
