  color: 
    #142943 !important; 
 
  font-size: 
    19px !important; 
 
} 
 
 
.empty-state p { 
 
  margin: 
    0 !important; 
 
  color: 
    #607894 !important; 
 
  font-size: 
    13px !important; 
 
} 
 
 
.empty-clear-btn { 
 
  margin-top: 
    16px !important; 
 
  height: 
    39px !important; 
 
  padding: 
    0 15px !important; 
 
  border: 
    1px solid #c7b5ff !important; 
 
  border-radius: 
    9px !important; 
 
  background: 
    #f4efff !important; 
 
  color: 
    #6336d1 !important; 
 
  font-weight: 
    800 !important; 
 
} 
 
 
/* ========================================================= 
   MODAL 
   ========================================================= */ 
 
.modal-overlay { 
 
  position: 
    fixed !important; 
 
  inset: 
    0 !important; 
 
  z-index: 
    1000000 !important; 
 
  padding: 
    20px !important; 
 
  display: 
    flex !important; 
 
  align-items: 
    center !important; 
 
  justify-content: 
    center !important; 
 
  background: 
    rgba(13,27,45,.67) !important; 
 
  backdrop-filter: 
    blur(4px) !important; 
 
} 
 
 
.application-modal { 
 
  width: 
    min(950px,96vw) !important; 
 
  max-height: 
    92vh !important; 
 
  overflow-y: 
    auto !important; 
 
  background: 
    #ffffff !important; 
 
  border-radius: 
    20px !important; 
 
  box-shadow: 
    0 30px 80px rgba(8,25,49,.32) !important; 
 
  scrollbar-width: 
    none !important; 
 
  -ms-overflow-style: 
    none !important; 
 
} 
 
 
.application-modal::-webkit-scrollbar { 
 
  width: 
    0 !important; 
 
  height: 
    0 !important; 
 
  display: 
    none !important; 
 
} 
 
 
.modal-header { 
 
  padding: 
    24px 28px !important; 
 
  display: 
    flex !important; 
 
  align-items: 
    flex-start !important; 
 
  justify-content: 
    space-between !important; 
 
  gap: 
    15px !important; 
 
  border-bottom: 
    1px solid #e1e8f0 !important; 
 
  background: 
    linear-gradient( 
      135deg, 
      #f6f1ff, 
      #f4f9ff 
    ) !important; 
 
} 
 
 
.modal-title { 
 
  display: 
    flex !important; 
 
  align-items: 
    center !important; 
 
  gap: 
    13px !important; 
 
} 
 
 
.modal-company-icon { 
 
  width: 
    55px !important; 
 
  height: 
    55px !important; 
 
  border-radius: 
    14px !important; 
 
  display: 
    flex !important; 
 
  align-items: 
    center !important; 
 
  justify-content: 
    center !important; 
 
  background: 
    #eae2ff !important; 
 
  color: 
    #6737d5 !important; 
 
  font-size: 
    18px !important; 
 
  font-weight: 
    900 !important; 
 
} 
 
 
.modal-title > div:last-child > span { 
 
  color: 
    #7039d9 !important; 
 
  font-size: 
    9px !important; 
 
  font-weight: 
    900 !important; 
 
  letter-spacing: 
    1.1px !important; 
 
} 
 
 
.modal-title h2 { 
 
  margin: 
    4px 0 2px !important; 
 
  color: 
    #10213e !important; 
 
  font-size: 
    23px !important; 
 
  font-weight: 
    850 !important; 
 
} 
 
 
.modal-title p { 
 
  margin: 
    0 !important; 
 
  color: 
    #59728e !important; 
 
  font-size: 
    13px !important; 
 
} 
 
 
.modal-close { 
 
  width: 
    37px !important; 
 
  height: 
    37px !important; 
 
  border: 
    0 !important; 
 
  border-radius: 
    50% !important; 
 
  background: 
    #edf2f8 !important; 
 
  color: 
    #38536f !important; 
 
  font-size: 
    24px !important; 
 
  cursor: 
    pointer !important; 
 
} 
 
 
.modal-status { 
 
  display: 
    grid !important; 
 
  grid-template-columns: 
    repeat(3,1fr) !important; 
 
  gap: 
    11px !important; 
 
  padding: 
    18px 28px !important; 
 
  background: 
    #fbfcfe !important; 
 
  border-bottom: 
    1px solid #e1e8f0 !important; 
 
} 
 
 
.modal-status div { 
 
  padding: 
    11px !important; 
 
  border-radius: 
    10px !important; 
 
  border: 
    1px solid #dfe7ef !important; 
 
  background: 
    #ffffff !important; 
 
} 
 
 
.modal-status span, 
.modal-field span, 
.progress-field span { 
 
  display: 
    block !important; 
 
  color: 
    #71849b !important; 
 
  font-size: 
    8px !important; 
 
  font-weight: 
    900 !important; 
 
  letter-spacing: 
    1px !important; 
 
} 
 
 
.modal-status strong, 
.modal-field strong, 
.progress-field strong { 
 
  display: 
    block !important; 
 
  margin-top: 
    5px !important; 
 
  color: 
    #182e4a !important; 
 
  font-size: 
    13px !important; 
 
  line-height: 
    1.35 !important; 
 
} 
 
 
.modal-section { 
 
  padding: 
    22px 28px !important; 
 
  border-bottom: 
    1px solid #e3e9f1 !important; 
 
} 
 
 
.modal-section-title span { 
 
  color: 
    #7039da !important; 
 
  font-size: 
    9px !important; 
 
  font-weight: 
    900 !important; 
 
  letter-spacing: 
    1.1px !important; 
 
} 
 
 
.modal-section-title h3 { 
 
  margin: 
    4px 0 15px !important; 
 
  color: 
    #152a45 !important; 
 
  font-size: 
    18px !important; 
 
  font-weight: 
    850 !important; 
 
} 
 
 
.modal-grid { 
 
  display: 
    grid !important; 
 
  grid-template-columns: 
    repeat(4,1fr) !important; 
 
  gap: 
    10px !important; 
 
} 
 
 
.modal-field { 
 
  min-height: 
    70px !important; 
 
  padding: 
    11px !important; 
 
  border-radius: 
    10px !important; 
 
  background: 
    #f7f9fc !important; 
 
  border: 
    1px solid #e0e7ef !important; 
 
} 
 
 
.progress-grid { 
 
  display: 
    grid !important; 
 
  grid-template-columns: 
    repeat(3,1fr) !important; 
 
  gap: 
    10px !important; 
 
} 
 
 
.progress-field { 
 
  padding: 
    12px !important; 
 
  border-radius: 
    10px !important; 
 
  background: 
    #f7f3ff !important; 
 
  border: 
    1px solid #ddd0ff !important; 
 
} 
 
 
.description-box { 
 
  padding: 
    14px !important; 
 
  border-radius: 
    11px !important; 
 
  background: 
    #f7f9fc !important; 
 
  border: 
    1px solid #e0e7ef !important; 
 
  color: 
    #405975 !important; 
 
  font-size: 
    13px !important; 
 
  line-height: 
    1.7 !important; 
 
} 
 
 
.modal-footer { 
 
  padding: 
    16px 28px !important; 
 
  display: 
    flex !important; 
 
  justify-content: 
    flex-end !important; 
 
  background: 
    #fbfcfe !important; 
 
} 
 
 
.modal-close-btn { 
 
  height: 
    42px !important; 
 
  padding: 
    0 18px !important; 
 
  border: 
    1px solid #d2dce8 !important; 
 
  border-radius: 
    10px !important; 
 
  background: 
    #ffffff !important; 
 
  color: 
    #38536f !important; 
 
  font-weight: 
    800 !important; 
 
  cursor: 
    pointer !important; 
 
} 
 
 
/* ========================================================= 
   MOBILE OVERLAY 
   ========================================================= */ 
 
.c360-sidebar-overlay { 
 
  display: 
    none !important; 
 
} 
 
 
/* ========================================================= 
   RESPONSIVE 
   ========================================================= */ 
 
@media (max-width:1200px) { 
 
  .summary-grid { 
 
    grid-template-columns: 
      repeat(2,minmax(0,1fr)) !important; 
 
  } 
 
 
  .applications-grid { 
 
    grid-template-columns: 
      repeat(2,minmax(0,1fr)) !important; 
 
  } 
 
 
  .modal-grid { 
 
    grid-template-columns: 
      repeat(2,1fr) !important; 
 
  } 
 
} 
 
 
/* ========================================================= 
   TABLET / MOBILE 
   ========================================================= */ 
 
@media (max-width:900px) { 
 
  .c360-left-sidebar { 
 
    position: 
      fixed !important; 
 
    top: 
      0 !important; 
 
    left: 
      0 !important; 
 
    bottom: 
      0 !important; 
 
    width: 
      285px !important; 
 
    min-width: 
      285px !important; 
 
    max-width: 
      285px !important; 
 
    height: 
      100vh !important; 
 
    transform: 
      translateX(-105%) !important; 
 
    box-shadow: 
      8px 0 28px rgba(15,10,40,.22) !important; 
 
  } 
 
 
  .campus360-applications.sidebar-open 
  .c360-left-sidebar { 
 
    transform: 
      translateX(0) !important; 
 
  } 
 
 
  .c360-right-page { 
 
    left: 
      0 !important; 
 
    width: 
      100vw !important; 
 
  } 
 
 
  .c360-sidebar-overlay { 
 
    position: 
      fixed !important; 
 
    inset: 
      0 !important; 
 
    z-index: 
      90 !important; 
 
    display: 
      block !important; 
 
    background: 
      rgba(15,10,40,.38) !important; 
 
  } 
 
 
  .campus360-applications.sidebar-closed 
  .c360-sidebar-overlay { 
 
    display: 
      none !important; 
 
  } 
 
 
  .c360-topbar { 
 
    height: 
      70px !important; 
 
    min-height: 
      70px !important; 
 
    flex-basis: 
      70px !important; 
 
    padding: 
      0 14px !important; 
 
  } 
 
} 
 
 
/* ========================================================= 
   SMALL MOBILE 
   ========================================================= */ 
 
@media (max-width:760px) { 
 
  .c360-page-content { 
 
    padding: 
      15px 10px 45px !important; 
 
  } 
 
 
  .applications-hero { 
 
    min-height: 
      160px !important; 
 
    padding: 
      25px 22px !important; 
 
    border-radius: 
      15px !important; 
 
    background:
      linear-gradient(
        135deg,
        #241044 0%,
        #351A61 52%,
        #45206D 100%
      ) !important;

    border-color:
      #5A357D !important;

  } 
 
 
  .applications-hero h1 { 
 
    font-size: 
      31px !important; 
 
    color:
      #ffffff !important;

  } 
 
 
  .applications-hero p { 
 
    font-size: 
      13px !important; 
 
    color:
      #E5DCF0 !important;

  } 
 
 
  .filter-section { 
 
    flex-direction: 
      column !important; 
 
    align-items: 
      stretch !important; 
 
  } 
 
 
  .search-box, 
  .status-select, 
  .clear-btn { 
 
    width: 
      100% !important; 
 
  } 
 
 
  .section-header { 
 
    flex-direction: 
      column !important; 
 
    align-items: 
      flex-start !important; 
 
    gap: 
      7px !important; 
 
  } 
 
 
  .modal-status, 
  .modal-grid, 
  .progress-grid { 
 
    grid-template-columns: 
      1fr !important; 
 
  } 
 
 
  .modal-overlay { 
 
    padding: 
      10px !important; 
 
  } 
 
} 
 
 
/* ========================================================= 
   MOBILE 650 
   ========================================================= */ 
 
@media (max-width:650px) { 
 
  .c360-topbar { 
 
    height: 
      68px !important; 
 
    min-height: 
      68px !important; 
 
    flex-basis: 
      68px !important; 
 
    padding: 
      0 11px !important; 
 
  } 
 
 
  .c360-page-heading { 
 
    display: 
      none !important; 
 
  } 
 
 
  .c360-top-profile-info, 
  .c360-profile-chevron { 
 
    display: 
      none !important; 
 
  } 
 
 
  .c360-top-profile { 
 
    padding-left: 
      3px !important; 
 
  } 
 
 
  .c360-top-icon { 
 
    width: 
      37px !important; 
 
    height: 
      37px !important; 
 
    min-width: 
      37px !important; 
 
  } 
 
 
  .c360-top-avatar { 
 
    width: 
      37px !important; 
 
    height: 
      37px !important; 
 
    min-width: 
      37px !important; 
 
  } 
 
 
  .summary-grid, 
  .applications-grid { 
 
    grid-template-columns: 
      1fr !important; 
 
  } 
 
 
  .application-header { 
 
    flex-wrap: 
      wrap !important; 
 
  } 
 
 
  .application-status { 
 
    margin-left: 
      auto !important; 
 
  } 
 
} 
 
 
/* ========================================================= 
   VERY SMALL MOBILE 
   ========================================================= */ 
 
@media (max-width:430px) { 
 
  .c360-menu-button { 
 
    width: 
      38px !important; 
 
    height: 
      38px !important; 
 
    min-width: 
      38px !important; 
 
  } 
 
 
  .applications-hero h1 { 
 
    font-size: 
      28px !important; 
 
    color:
      #ffffff !important;

  } 
 
 
  .applications-hero p {

    color:
      #E5DCF0 !important;

  }


  .hero-eyebrow {

    color:
      #DCCBFF !important;

  }


  .hero-dot {

    background:
