/* ========================================================= 
   FINAL FULL VIEW 
   ========================================================= */ 
 
/* Hide outer browser/page scrollbar */ 
 
html:has(.campus360-applications), 
body:has(.campus360-applications) { 
 
  width: 
    100% !important; 
 
  height: 
    100% !important; 
 
  margin: 
    0 !important; 
 
  padding: 
    0 !important; 
 
  overflow: 
    hidden !important; 
 
} 
 
 
/* Main content scrolls */ 
 
.c360-right-page { 
 
  overflow-y: 
    auto !important; 
 
  overflow-x: 
    hidden !important; 
 
  scrollbar-width: 
    none !important; 
 
  -ms-overflow-style: 
    none !important; 
 
} 
 
 
.c360-right-page::-webkit-scrollbar { 
 
  width: 
    0 !important; 
 
  height: 
    0 !important; 
 
  display: 
    none !important; 
 
} 
 
 
/* Sidebar scrolls without visible scrollbar */ 
 
.c360-sidebar-nav { 
 
  overflow-y: 
    auto !important; 
 
  overflow-x: 
    hidden !important; 
 
  scrollbar-width: 
    none !important; 
 
  -ms-overflow-style: 
    none !important; 
 
} 
 
 
.c360-sidebar-nav::-webkit-scrollbar { 
 
  width: 
    0 !important; 
 
  height: 
    0 !important; 
 
  display: 
    none !important; 
 
} 
 
 
/* Modal scrolls without visible scrollbar */ 
 
.application-modal { 
 
  overflow-y: 
    auto !important; 
 
  scrollbar-width: 
    none !important; 
 
  -ms-overflow-style: 
    none !important; 
 
} 
 
 
.application-modal::-webkit-scrollbar { 
 
  width: 
    0 !important; 
 
  height: 
    0 !important; 
 
  display: 
    none !important; 
 
} 
 
 
/* ========================================================= 
   FINAL NAVBAR / HERO SEPARATION 
   ========================================================= */ 
 
/* 
   The white Campus360 navbar always stays above 
   the page content while scrolling. 
*/ 
 
.c360-topbar { 
 
  background: 
    #ffffff !important; 
 
  position: 
    sticky !important; 
 
  top: 
    0 !important; 
 
  z-index: 
    5000 !important; 
 
} 
 
 
/* 
   Hero begins below the white navbar with 
   its own visible spacing. 
*/ 
 
.c360-page-content { 
 
  position: 
    relative !important; 
 
  z-index: 
    1 !important; 
 
  padding-top: 
    18px !important; 
 
} 
 
 
/* 
   Keep the purple hero fully below the navbar. 
*/ 
 
.applications-hero { 
 
  position: 
    relative !important; 
 
  z-index: 
    1 !important; 
 
  margin-top: 
    0 !important; 
 
  background:
    linear-gradient(
      135deg,
      #241044 0%,
      #351A61 52%,
      #45206D 100%
    ) !important;

  border:
    1px solid #5A357D !important;

  color:
    #ffffff !important;

}


.applications-hero h1 {

  color:
    #ffffff !important;

}


.applications-hero p {

  color:
    #E5DCF0 !important;

}


.applications-hero .hero-eyebrow {

  color:
    #DCCBFF !important;

}


.applications-hero .hero-dot {

  background:
    #C4B5FD !important;

}


/* ========================================================= 
   FINAL CAMPUS360 FULLSCREEN 
   ========================================================= */ 
 
.campus360-applications { 
 
  width: 
    100vw !important; 
 
  height: 
    100vh !important; 
 
  margin: 
    0 !important; 
 
  padding: 
    0 !important; 
 
}

sp_widget.script:
(function() {

    /* =====================================================
       INITIAL DATA
       ===================================================== */

    data.success = false;

    data.message = '';

    data.student = null;

    data.applications = [];

    data.stats = {

        total: 0,

        submitted: 0,

        shortlisted: 0,

        interview: 0

    };


    /* =====================================================
       STUDENT ID
       ===================================================== */

    var studentId =
        $sp.getParameter('student') ||
        'STU_TEST_001';


    /* =====================================================
       FIND STUDENT
       ===================================================== */

    var studentGR =
        new GlideRecord(
            'x_snc_campus360_student_master'
        );


    studentGR.addQuery(
        'student_id',
        studentId
    );


    studentGR.query();


    if (!studentGR.next()) {

        data.message =
            'Student record not found.';

        return;

    }


    var studentSysId =
        studentGR.getUniqueValue();


    /* =====================================================
       STUDENT INFORMATION
       ===================================================== */

    data.student = {

        sys_id:
            studentSysId,

        student_id:
            studentGR.getValue(
                'student_id'
            ) || '',

        student_name:
            studentGR.getValue(
                'student_name'
            ) || '',

        email:
            studentGR.getValue(
                'email'
            ) || '',

        phone_number:
            studentGR.getValue(
                'phone_number'
            ) || '',

        degree:
            studentGR.getDisplayValue(
                'degree'
            ) || '',

        branch:
            studentGR.getDisplayValue(
                'branch'
            ) || '',

        batch:
            studentGR.getValue(
                'batch'
            ) || '',

        cgpa:
            studentGR.getValue(
                'cgpa'
            ) || ''

    };


    /* =====================================================
       LOAD STUDENT APPLICATIONS
       ===================================================== */

    loadStudentApplications();


    /* =====================================================
       LOAD APPLICATIONS
       ===================================================== */

    function loadStudentApplications() {

        var appGR =
            new GlideRecord(
                'x_snc_campus360_student_application'
            );


        /*
         * IMPORTANT:
         *
         * Only get application records belonging
         * to the current student.
         *
         * We DO NOT filter by application_id.
         *
         * This is important because a newly saved
         * application may have:
         *
         * student_response = Apply
         * application_status = Submitted
         *
         * even if application_id has not been
         * populated yet.
         */

        appGR.addQuery(
            'student',
            studentSysId
        );


        /*
         * Show latest applications first.
         */

        appGR.orderByDesc(
            'sys_created_on'
        );


        appGR.query();


        while (appGR.next()) {


            /* =============================================
               READ CHOICE DISPLAY VALUES
               ============================================= */

            var applicationStatus =
                (
                    appGR.getDisplayValue(
                        'application_status'
                    ) || ''
                ).trim();


            var studentResponse =
                (
                    appGR.getDisplayValue(
                        'student_response'
                    ) || ''
                ).trim();


            /*
             * Normalize values so this works whether
             * ServiceNow stores:
             *
             * Apply
             * apply
             * APPLY
             *
             * and similarly:
             *
             * Submitted
             * submitted
             * SUBMITTED
             */

            var normalizedResponse =
                studentResponse.toLowerCase();


            var normalizedStatus =
                applicationStatus.toLowerCase();


            /* =============================================
               DETERMINE WHETHER THIS IS AN APPLIED RECORD
               ============================================= */

            var isApplied =
                false;


            /*
             * PRIMARY CONDITION
             *
             * If the student selected Apply,
             * this is an applied application.
             */

            if (
                normalizedResponse === 'apply'
            ) {

                isApplied = true;

            }


            /*
             * SECOND CONDITION
             *
             * If application status is Submitted,
             * this is also considered an applied
             * application.
             */

            if (
                normalizedStatus === 'submitted'
            ) {

                isApplied = true;

            }


            /*
             * If the record is not actually applied,
             * do not show it on this page.
             */

            if (!isApplied) {

                continue;

            }


            /* =============================================
               APPLICATION OBJECT
               ============================================= */

            var application = {

                sys_id:
                    appGR.getUniqueValue(),

                application_id:
                    appGR.getValue(
                        'application_id'
                    ) || '',

                application_status:
                    applicationStatus,

                assessment_status:
                    appGR.getDisplayValue(
                        'assessment_status'
                    ) || '',

                offer_status:
                    appGR.getDisplayValue(
                        'offer_status'
                    ) || '',

                student_response:
                    studentResponse,

                applied_date:
                    appGR.getDisplayValue(
                        'applied_date'
                    ) || '',

                shortlisted:
                    appGR.getDisplayValue(
                        'shortlisted'
                    ) || '',

                interview_status:
                    appGR.getDisplayValue(
                        'interview_status'
                    ) || '',

                ai_match_score:
                    appGR.getValue(
                        'ai_match_score'
                    ) || '',

                opportunity_sys_id:
                    appGR.getValue(
                        'opportunity'
                    ) || '',


                /* =========================================
                   OPPORTUNITY DATA
                   ========================================= */

                opportunity_title: '',

                company: '',

                opportunity_type: '',

                location: '',

                ctc_stipend: '',

                minimum_cgpa: '',

                eligible_branches: '',

                required_skills: '',

                job_description: '',

                drive_date: '',

                application_deadline: ''

            };


            /* =============================================
               GET RELATED OPPORTUNITY
               ============================================= */

            if (
                application.opportunity_sys_id
            ) {

                var opportunityGR =
                    new GlideRecord(
                        'x_snc_campus360_placement_opportunity'
                    );


                if (
                    opportunityGR.get(
                        application.opportunity_sys_id
                    )
                ) {

                    application.opportunity_title =
                        opportunityGR.getValue(
                            'opportunity_title'
                        ) || '';


                    application.company =
                        opportunityGR.getDisplayValue(
                            'company'
                        ) || '';


                    application.opportunity_type =
                        opportunityGR.getDisplayValue(
                            'opportunity_type'
                        ) || '';


                    application.location =
                        opportunityGR.getValue(
                            'location'
                        ) || '';


                    application.ctc_stipend =
                        opportunityGR.getValue(
                            'ctc_stipend'
                        ) || '';


                    application.minimum_cgpa =
                        opportunityGR.getValue(
                            'minimum_cgpa'
                        ) || '';


                    application.eligible_branches =
                        opportunityGR.getValue(
                            'eligible_branches'
                        ) || '';


                    application.required_skills =
                        opportunityGR.getValue(
                            'required_skills'
                        ) || '';


                    application.job_description =
                        opportunityGR.getValue(
                            'job_description'
                        ) || '';


                    application.drive_date =
                        opportunityGR.getDisplayValue(
                            'drive_date'
                        ) || '';


                    application.application_deadline =
                        opportunityGR.getDisplayValue(
                            'application_deadline'
                        ) || '';

                }

            }


            /* =============================================
               ADD APPLICATION
               ============================================= */

            data.applications.push(
                application
            );


            /* =============================================
               STATISTICS
               ============================================= */

            data.stats.total++;


            /*
             * Since this page contains only applied
             * applications, every record here is
             * considered submitted/applied.
             */

            data.stats.submitted++;


            /* =============================================
               SHORTLISTED
               ============================================= */

            var shortlist =
                (
                    application.shortlisted ||
                    ''
                ).toLowerCase()
                .trim();


            if (
                shortlist === 'true' ||
                shortlist === 'yes' ||
                shortlist === 'shortlisted'
            ) {

                data.stats.shortlisted++;

            }


            /* =============================================
               INTERVIEW
               ============================================= */

            var interview =
                (
                    application.interview_status ||
                    ''
                ).toLowerCase()
                .trim();


            if (
                interview &&
                interview !== 'not scheduled' &&
                interview !== 'not_scheduled' &&
                interview !== 'none' &&
                interview !== 'pending'
            ) {

                data.stats.interview++;

            }

        }


        /* =============================================
           RESPONSE
           ============================================= */

        data.success = true;


        if (
            data.applications.length > 0
        ) {

            data.message =
                'Student applications loaded successfully.';

        } else {

            data.message =
                'No submitted applications found.';

        }

    }


})();


/* =====================================================
   AI ASSISTANT WIDGET
   ===================================================== */

data.aiWidget =
    $sp.getWidget(
        'campus360_ai_assistant'
    );
